window.STORY_CHAPTERS["c9e1359f944443b19"]={"id":"c9e1359f944443b19","lines":[{"uid":"talk.vc.home_rank_renri_1#originalText","id":"talk.vc.home_rank_renri_1","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"你最近变强了很多呢。大家都对你的成长速度感到很惊讶。","en":"You've gotten really strong, lately! Everyone is surprised. Especially how fast you've become.","ja":"最近、とても強くなってるねみんなもびっくりしてたよ君の成長速度に"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_renri_2#originalText","id":"talk.vc.home_rank_renri_2","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"真厉害！你已经变到这么强了，真让我吃惊。","en":"That's amazing! I'm surprised that you've gotten this strong!","ja":"すごいじゃないか!もうこんなに強くなるなんて驚いたよ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_renri_3#originalText","id":"talk.vc.home_rank_renri_3","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"已经变到这么强了。我也要变得更强，不能输给你！","en":"To think that you've gotten this strong! I also need to get stronger so that I don't fall behind!","ja":"もうこんなに強くなったんだ僕も、負けないようにもっと強くならないと!"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_renri_4#originalText","id":"talk.vc.home_rank_renri_4","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"真是的，你到底……是打算变得多强啊？","en":"Wow...  Just how much stronger are you gonna get?","ja":"本当に、君って人は……どこまで強くなるんだい?"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_renri_5#originalText","id":"talk.vc.home_rank_renri_5","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"像我这样的人说不定已经赢不过你了……我会努力，不被你抛下的。","en":"I probably won't be able to win anymore... But I will try my best to not leave you behind!","ja":"もう僕なんかじゃ勝てないかもしれないけど……君に置いていかれないように、頑張るよ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_ronye_1#originalText","id":"talk.vc.home_rank_ronye_1","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"学长的强大，我亲身体悟到了！","en":"I learned firsthand just how powerful you are!","ja":"先輩の強さ、身をもって思い知りました! "},"kind":"dialogue"},{"uid":"talk.vc.home_rank_ronye_2#originalText","id":"talk.vc.home_rank_ronye_2","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"您又变强了呢。恭喜您！","en":"You've become even stronger, I see. Congratulations!","ja":"また強くなられたのですねおめでとうございます! "},"kind":"dialogue"},{"uid":"talk.vc.home_rank_ronye_3#originalText","id":"talk.vc.home_rank_ronye_3","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"看、看不见！剑的动作太犀利了……","en":"I...can't even see your sword! It's moving so swiftly.","ja":"み、見えません! 剣の動きが、鋭すぎて……"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_ronye_4#originalText","id":"talk.vc.home_rank_ronye_4","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"我会尽己所能，把学长的强悍化作自己的实力！","en":"I would love to learn from you, and gain even a fraction of your strength.","ja":"先輩の強さ、少しでも自分のものにしてみせます! "},"kind":"dialogue"},{"uid":"talk.vc.home_rank_ronye_5#originalText","id":"talk.vc.home_rank_ronye_5","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"能够和学长匹敌的人，世上真的存在吗？","en":"I wonder if there is an opponent who is truly worthy of you?","ja":"先輩と戦えるような相手が本当に居るのでしょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_sachi_1#originalText","id":"talk.vc.home_rank_sachi_1","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"你越来越强了呢。我也要加油，不能输给你！","en":"You're just getting stronger and stronger. I need to take a leaf from your book!","ja":"どんどん強くなってるんだね私も、負けないよう頑張る!"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_sachi_2#originalText","id":"talk.vc.home_rank_sachi_2","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"变强就代表，你一直有在前往危险的地方对吧。……要小心一点喔。","en":"Since you've leveled-up, I guess that means you're venturing to more dangerous areas. Be careful, okay?","ja":"強くなったということは危険な場所に行っているんだよね……気をつけてね"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_sachi_3#originalText","id":"talk.vc.home_rank_sachi_3","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"总有一天，我也要变得跟你一样强才行呢。","en":"Someday, I'll have to get as strong as you.","ja":"私も、いつか君みたいに強くならないといけないよね"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_sachi_4#originalText","id":"talk.vc.home_rank_sachi_4","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"恭喜你升级。我也想要变强，你可以陪我练习一下吗？","en":"Congrats on leveling up! Can I train with you for a bit? I want to become stronger, too.","ja":"レベルアップおめでとう私も強くなりたいから、少しだけ練習に付き合ってくれる?"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_sachi_5#originalText","id":"talk.vc.home_rank_sachi_5","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"你一定做了我无法想像的努力吧。我很尊敬你喔。","en":"You must've worked harder than I could imagine. I really do respect you.","ja":"きっと、想像もつかないくらい頑張ったんだね尊敬するよ、君を"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_scheta_1#originalText","id":"talk.vc.home_rank_scheta_1","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"现在只要你站在我面前，我就会斩了你。要站在我面前的话，你必须变得更坚硬才行。","en":"I will cut you down if you stand in front of me. Toughen up if you dare to do so.","ja":"今私の前に立ったら斬ってしまう立つなら、もっと硬くなって"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_scheta_2#originalText","id":"talk.vc.home_rank_scheta_2","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"你稍微变坚硬了呢。但也有很多软弱的地方。","en":"You've toughened up a bit. But you're still soft in a lot of spots.","ja":"少し硬くなってきたけど柔らかいところもたくさんある"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_scheta_3#originalText","id":"talk.vc.home_rank_scheta_3","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"你坚硬的地方一点一点地变多了。","en":"Looks like you've gradually grown stronger in some places.","ja":"少しずつ、硬いところが増えてきたみたい"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_scheta_4#originalText","id":"talk.vc.home_rank_scheta_4","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"……说不定，和你的话我可以尽全力战斗呢。","en":"...Whenever I am with you, I really can fight with all my strength.","ja":"……もしかしたら、あなたとなら本当に全力で戦えるのかも"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_scheta_5#originalText","id":"talk.vc.home_rank_scheta_5","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"没有软弱的地方。……我希望可以和你好好地对战。","en":"You don't have seem to have any weak spots. ...I will fight you, properly. Show me what you're made of.","ja":"どこにも、柔らかいところがない……ちゃんと、あなたと立ち合って剣を合わせてみたい"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_selka_1#originalText","id":"talk.vc.home_rank_selka_1","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"好厉害呢。你这样都可以当侍卫了吧？","en":"Well, I'm quite impressed. If you keep it up, you might be able to become a knight.","ja":"すごいわねそれなら衛士になれるんじゃない?"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_selka_2#originalText","id":"talk.vc.home_rank_selka_2","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"说不定，你在卢利特是最强的呢！","en":"You just might be the strongest in Rulid now!","ja":"もしかしたら、ルーリッドで一番強いかもしれないわ!"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_selka_3#originalText","id":"talk.vc.home_rank_selka_3","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"你愿意在变强后，保护村中所有人吗……？谢谢你。","en":"Will you protect everyone in Rulid, now that you've gotten stronger? Thank you. That's so sweet of you.","ja":"強くなって、村のみんなを守ってくれるの……?ありがとう"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_selka_4#originalText","id":"talk.vc.home_rank_selka_4","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"你又变强啦……总觉得你好像去了很远的地方。","en":"You've gotten even stronger. I feel so distant from you now.","ja":"また強くなったんだ……なんだか、遠くに行っちゃうみたい"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_selka_5#originalText","id":"talk.vc.home_rank_selka_5","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"就算你变强了，但在教会吃饭的样子还是没变呢。我稍微安心了。","en":"No matter how powerful you get, you're still a slob when you eat. That's actually reassuring.","ja":"強くなっても、教会でご飯を食べてる姿は変わらないのね少し安心しちゃった"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_seven_1#originalText","id":"talk.vc.home_rank_seven_1","speaker":{"cn":"赛玟","en":"Seven","ja":"セブン"},"text":{"cn":"你好像稍微变强了呢。不过，你的程度不只这样吧！","en":"I see you've gotten a bit stronger. But I'm still more powerful than you!","ja":"少しは強くなったみたいねでも、まだまだこんなものじゃないはずよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_seven_2#originalText","id":"talk.vc.home_rank_seven_2","speaker":{"cn":"赛玟","en":"Seven","ja":"セブン"},"text":{"cn":"哼，还不错嘛。只是，你也不会满足于此吧！","en":"Fuun, so you do got it! Don't get cocky though! ","ja":"ふうん、やるじゃないまさか、このくらいで満足するとは思わないけど!"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_seven_3#originalText","id":"talk.vc.home_rank_seven_3","speaker":{"cn":"赛玟","en":"Seven","ja":"セブン"},"text":{"cn":"呵呵，你果然变强了呢。就如我所料。","en":"Fufu, you're going to get stronger, as I suspected. ","ja":"ふふ、やっぱりあなた強くなるわねあたしの思った通りだわ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_seven_4#originalText","id":"talk.vc.home_rank_seven_4","speaker":{"cn":"赛玟","en":"Seven","ja":"セブン"},"text":{"cn":"不锻炼自己到一定程度，是无法获得这等强大的。看来你对自己相当严格呢。","en":"You wouldn't be able to get this strong if you hadn't trained for it. You're quiet a stoic one.","ja":"よほど自分を鍛えないとこれほどの強さは手に入らないわずいぶんストイックなのね"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_seven_5#originalText","id":"talk.vc.home_rank_seven_5","speaker":{"cn":"赛玟","en":"Seven","ja":"セブン"},"text":{"cn":"我已经没什么好说的了。我也得向你看齐，好好锻炼自己才行。","en":"I have nothing else to say to you. I need to learn from you and get stronger myself.","ja":"もう、何も言うことはないわあたしも、あなたを見習って自分を鍛え上げないと"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_shasta_1#originalText","id":"talk.vc.home_rank_shasta_1","speaker":{"cn":"夏斯达","en":"Shasta","ja":"シャスター"},"text":{"cn":"你的剑术很值得一看。试试攻击我吧。","en":"Your sword skills are promising. Come, try and strike at me!","ja":"お前の剣筋、見所がある試しに、俺に打ち込んでこい"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_shasta_2#originalText","id":"talk.vc.home_rank_shasta_2","speaker":{"cn":"夏斯达","en":"Shasta","ja":"シャスター"},"text":{"cn":"嗯……果然很有潜能。但还不足够。是你的话，一定可以变得更强。","en":"Hm.. As I thought. There is quality in there. However, it's still not enough. You can still get stronger.","ja":"ふむ……やはり素質があるなしかし、まだまだ不十分だお前なら、もっと強くなれる"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_shasta_3#originalText","id":"talk.vc.home_rank_shasta_3","speaker":{"cn":"夏斯达","en":"Shasta","ja":"シャスター"},"text":{"cn":"跟之前不一样的强大。你果然很有趣。","en":"This strength is different from what I saw before. You truly are an interesting one.","ja":"前とは見違える強さだやはり面白いな、お前は"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_shasta_4#originalText","id":"talk.vc.home_rank_shasta_4","speaker":{"cn":"夏斯达","en":"Shasta","ja":"シャスター"},"text":{"cn":"锻炼到这个程度的人，在暗黑骑士团也没有几个，我很佩服你。","en":"I don't think there is anyone as well-trained as you even among the Dark Knights! I'm impressed.","ja":"ここまで鍛え上げた者は暗黒騎士団でもそうはいまい感服したぞ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_shasta_5#originalText","id":"talk.vc.home_rank_shasta_5","speaker":{"cn":"夏斯达","en":"Shasta","ja":"シャスター"},"text":{"cn":"说不定你已经比我更强了。看来你很适合继承我的意志。","en":"You are probably stronger than even me now. You are more than worthy to continue on my will.","ja":"もはや俺よりも強いかもしれんな俺の意志を継ぐのはお前こそがふさわしい"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_silica_1#originalText","id":"talk.vc.home_rank_silica_1","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"你已经升级了吗？我好像还要花点时间……","en":"You got a higher rank already? It's gonna take me a little while longer.","ja":"もうランクアップですか? あたしはもうちょっとかかりそうです……"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_silica_2#originalText","id":"talk.vc.home_rank_silica_2","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"哇，真厉害！你已经升级到那么高啦！","en":"Wow, I'm impressed! Look how quickly you improved!","ja":"わあ、さすがです! もうそんなにランクアップしちゃうなんて! "},"kind":"dialogue"},{"uid":"talk.vc.home_rank_silica_3#originalText","id":"talk.vc.home_rank_silica_3","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"你又变强了呢。……下次可以请你陪我练习吗？","en":"You got stronger again, I see. Would you help me practice my form sometime?","ja":"また強くなったんですね……今度、少し練習をお手伝いしてもらってもいいですか? "},"kind":"dialogue"},{"uid":"talk.vc.home_rank_silica_4#originalText","id":"talk.vc.home_rank_silica_4","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"你的等级已经那么……我也要再加点油才行。","en":"Wow, your rank is so high already! I need to put in more effort.","ja":"もう、そんなにランクが……あたしも、もう少し頑張らないと"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_silica_5#originalText","id":"talk.vc.home_rank_silica_5","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"对我来说，你从以前就一直是最强的剑士！","en":"You've always been the strongest swordsman to me!","ja":"あたしにとっては、前からずっと最強の剣士さんです! "},"kind":"dialogue"},{"uid":"talk.vc.home_rank_sinon_1#originalText","id":"talk.vc.home_rank_sinon_1","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"还行啦。不过，你的程度不只这样吧？","en":"Not bad. But you're going at a good pace.","ja":"まあまあねでも、この程度じゃないでしょう? "},"kind":"dialogue"},{"uid":"talk.vc.home_rank_sinon_2#originalText","id":"talk.vc.home_rank_sinon_2","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"你稍微变强了呢，我果然没看走眼。","en":"You've gotten stronger. I knew I saw potential in you.","ja":"少しは強くなったのねやっぱり、私の見込んだとおりだった"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_sinon_3#originalText","id":"talk.vc.home_rank_sinon_3","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"算是发挥出真本事了吧？呵呵，但我觉得你还可以变得更强。","en":"That was a display of your true skills, I guess. Hehe. But I'm sure you can get stronger.","ja":"本領発揮といったところかしらふふ、でももっと強くなれると思うわよ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_sinon_4#originalText","id":"talk.vc.home_rank_sinon_4","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"如果1对1战斗，我一定赢不了。不过，我也还……","en":"If we fought 1-1, I'd lose. But I've got some fight in me yet...","ja":"1対1で戦ったら、きっと勝てないわでも、私だってまだ……"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_sinon_5#originalText","id":"talk.vc.home_rank_sinon_5","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"感觉你已经处在不同次元了。能和那样的人一起战斗，是我的光荣。","en":"It's like we're on whole different levels now. I'm honored to fight with you.","ja":"もう次元が違う感じねそんな人と一緒に戦えて光栄だわ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_sortiliena_1#originalText","id":"talk.vc.home_rank_sortiliena_1","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"刚刚那击剑技很犀利呢。保持那个状态，你会变强的。","en":"That was a rather sharp hit. Keep it up and you're sure to become stronger.","ja":"なかなかに鋭い剣撃だったぞその調子なら、お前は強くなる"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_sortiliena_2#originalText","id":"talk.vc.home_rank_sortiliena_2","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"看来你一直有保持修练，夙夜匪懈呢。而其成果浮现了。","en":"I hear you've been training relentlessly. And it shows.","ja":"たゆまず修練を続けているようだなその成果が出たんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_sortiliena_3#originalText","id":"talk.vc.home_rank_sortiliena_3","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"真有你的。但是，这还不是尽头，你还会变得更判若两人。","en":"I knew you could do it. But this is not your limit, you can aim even higher!","ja":"さすがだなだが、これが底ではないだろうもっともっと強くなるぞ、お前は"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_sortiliena_4#originalText","id":"talk.vc.home_rank_sortiliena_4","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"太杰出了。我也有勤加锻炼，但还是远不如你。","en":"Splendid. And I thought I was disciplined.","ja":"見事だ私も鍛錬を積んだつもりだがお前には遠く及ばない"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_sortiliena_5#originalText","id":"talk.vc.home_rank_sortiliena_5","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"虽说人界宽广，但能与你比肩者想必可数。能跟你携手，是我的骄傲。","en":"I think I would be hard pressed to find someone as skilled as you, in all the world. I am truly proud to be your friend.","ja":"人界広しと言えど、お前に迫る者は、そういないだろうお前と共にいられたこと、誇りに思う"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_sortiliena_child_1#originalText","id":"talk.vc.home_rank_sortiliena_child_1","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"你最近很努力呢。我也不能输。","en":"You've been working hard lately. I can't let you out-perform me!","ja":"最近、とても頑張ってるな私も負けていられない"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_sortiliena_child_2#originalText","id":"talk.vc.home_rank_sortiliena_child_2","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"你变强的身影，真的很帅呢。有鼓舞到我喔。","en":"You look so dashing when you train. It's very inspiring to me.","ja":"強くなる姿は、とてもかっこいいな励みになるよ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_sortiliena_child_3#originalText","id":"talk.vc.home_rank_sortiliena_child_3","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"你的剑法……真是有趣。希望你可以教我。","en":"Your form...is very intriguing. Would you teach it to me?","ja":"あなたの剣筋……興味深いよかったら教えてほしい"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_sortiliena_child_4#originalText","id":"talk.vc.home_rank_sortiliena_child_4","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"或许我已经赢不过你了，但你还愿意再陪我练一次吗？","en":"I may no longer be able to defeat you now. Would you give me a workout?","ja":"もう、私では勝てないかもしれないが一度胸を貸してくれないか"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_sortiliena_child_5#originalText","id":"talk.vc.home_rank_sortiliena_child_5","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"希望有一天，我也可以跟你并驾齐驱。","en":"I hope that someday, I can stand beside you as an equal.","ja":"いつか、私もあなたに並び立つようになりたいな"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_strea_1#originalText","id":"talk.vc.home_rank_strea_1","speaker":{"cn":"斯朵蕾雅","en":"Strea","ja":"ストレア"},"text":{"cn":"好耶好耶！好像变强了喔！","en":"This is great! I feel like I've gotten stronger!","ja":"いいねいいね!強くなってきた感じがするよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_strea_2#originalText","id":"talk.vc.home_rank_strea_2","speaker":{"cn":"斯朵蕾雅","en":"Strea","ja":"ストレア"},"text":{"cn":"喔，这身手真敏捷！你也练了很久呢，好厉害！","en":"You're quiet the sharp one! It's amazing how much you've honed your skills!","ja":"おお、鋭い身のこなし!ずいぶん鍛えたんだね、すごい!"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_strea_3#originalText","id":"talk.vc.home_rank_strea_3","speaker":{"cn":"斯朵蕾雅","en":"Strea","ja":"ストレア"},"text":{"cn":"不知不觉，你就变得这么强了呢－－我也不能输给你！","en":"You got a lot stronger while I wasn't looking. I'd better step up so I don't get left behind.","ja":"いつの間にか、こんなに強くなっちゃったんだねーアタシも負けてられないな!"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_strea_4#originalText","id":"talk.vc.home_rank_strea_4","speaker":{"cn":"斯朵蕾雅","en":"Strea","ja":"ストレア"},"text":{"cn":"哇，我完全赢不了你！你真的很强呢。","en":"Uwa. I conceed! I won't be your enemy! You're quiet the strong one.","ja":"うわー、アタシじゃもう全然敵わないよ!強いんだね、キミは"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_strea_5#originalText","id":"talk.vc.home_rank_strea_5","speaker":{"cn":"斯朵蕾雅","en":"Strea","ja":"ストレア"},"text":{"cn":"今后你一定会持续变强吧。我也很想，一直在旁边看着你变强。","en":"You'll only continue to get stronger going forward. I want to see that through to the end.","ja":"きっとこれからも、キミはずっと強くなっていくんだろうねアタシも、それをずっと見てたいな"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_subtilizer_1#originalText","id":"talk.vc.home_rank_subtilizer_1","speaker":{"ja":"サトライザー"},"text":{"ja":"まだまだ、とるに足らん強さだな"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_subtilizer_4#originalText","id":"talk.vc.home_rank_subtilizer_4","speaker":{"ja":"サトライザー"},"text":{"ja":"ほう、面白くなってきたなその調子で鍛え抜けば、さぞ甘き魂が練られることだろう"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_subtilizer_5#originalText","id":"talk.vc.home_rank_subtilizer_5","speaker":{"ja":"サトライザー"},"text":{"ja":"いいだろう。お前の魂とくと味あわせてくれ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_suguha_1#originalText","id":"talk.vc.home_rank_suguha_1","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"你升级了呢！好厉害！大概是练习的成果浮现了吧？","en":"Your rank went up! Way to go! All that training paid off.","ja":"ランクアップ、さすがだね! 練習の成果が出てるんじゃない? "},"kind":"dialogue"},{"uid":"talk.vc.home_rank_suguha_2#originalText","id":"talk.vc.home_rank_suguha_2","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"好厉害～你已经变得那么强了啊？","en":"Wow! How'd you get so strong so fast?","ja":"すごーい、もうそんなに強くなったの? "},"kind":"dialogue"},{"uid":"talk.vc.home_rank_suguha_3#originalText","id":"talk.vc.home_rank_suguha_3","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"你今天的表现很棒呢，我也不能输啊。","en":"You moved really well today. I need to up my game.","ja":"今日の動き、すごかったねあたしも負けてられないな"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_suguha_4#originalText","id":"talk.vc.home_rank_suguha_4","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"讨厌，真是比不过你。你完全是大家的队长了呢！","en":"Man, no one can hold a candle to you anymore. You're totally our leader!","ja":"もう、ちょっと敵わないかなあすっかりみんなのリーダーだよね! "},"kind":"dialogue"},{"uid":"talk.vc.home_rank_suguha_5#originalText","id":"talk.vc.home_rank_suguha_5","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"这就是所谓的高手吧？动作优美又俐落……我要跟你看齐呢。","en":"Is this what a master looks like? Your moves are almost like dancing... O, teach me your ways!","ja":"達人ってこういうことなのかな動きがキレイで無駄がなくて……見習いたいよ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_tiese_1#originalText","id":"talk.vc.home_rank_tiese_1","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"我无法相信，学长竟会列于首席、次席剑士之下。","en":"I find it difficult to believe that you rank below the First and the Second Seats.","ja":"先輩が主席剣士の方や次席の方の下にいるのが信じられません"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_tiese_2#originalText","id":"talk.vc.home_rank_tiese_2","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"学长总是不怠忽努力呢。我也想向您学习。","en":"You never neglect your daily training, I see. I need to be more like you.","ja":"先輩は常に努力を怠らないのですね私も見習いたいです"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_tiese_3#originalText","id":"talk.vc.home_rank_tiese_3","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"这么快速的剑……我接不下。","en":"Your attacks are so swift! I can't block them.","ja":"こんなに速い剣は……受け止められません"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_tiese_4#originalText","id":"talk.vc.home_rank_tiese_4","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"这就是《艾恩葛朗特流》的本事对吧？我也肯定要把这招……","en":"Now I see how powerful Aincrad style is. I would love to be able to master your moves!","ja":"これが《アインクラッド流》の強さなんですねあたしも、きっとこの技を……"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_tiese_5#originalText","id":"talk.vc.home_rank_tiese_5","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"请让我一直追着学长的背影！","en":"Please, let me keep striving to be as skilled as you!","ja":"先輩の背中、あたしにずっと追いかけさせてください! "},"kind":"dialogue"},{"uid":"talk.vc.home_rank_tiese_child_1#originalText","id":"talk.vc.home_rank_tiese_child_1","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"你的剑很快……我想你一定会继续变得更强吧。","en":"Your sword is so fast... You'll definitely get even stronger!","ja":"あなたの剣、すごく速い……きっと、もっとずっと強くなるのね"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_tiese_child_2#originalText","id":"talk.vc.home_rank_tiese_child_2","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"很厉害的招式！你有一直在练剑吧。","en":"What technique! Looks like you've been honing your sword skills this whole time!","ja":"素晴らしい技です!ずっと剣の稽古をしていたんですね"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_tiese_child_3#originalText","id":"talk.vc.home_rank_tiese_child_3","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"说不定比起我们的老师，你还比较强……","en":"You are probably already stronger than my teacher...","ja":"もうあたしの先生よりもあなたの方が強いかもしれない……"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_tiese_child_4#originalText","id":"talk.vc.home_rank_tiese_child_4","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"像你这样的人，一定可以在剑武大会胜出获得爵位吧。","en":"If someone like you entered the Imperial Tournament, you would definitely get the title!","ja":"あなたのような人がきっと剣武大会に出て爵位をもらうのね"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_tiese_child_5#originalText","id":"talk.vc.home_rank_tiese_child_5","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"我一直在看着你变得越来越强。我也得快点追上你才行。","en":"I've been watching this whole time. Seeing you get stronger makes me want to hurry up and catch up!","ja":"ずっと見ていましたあなたが強くなっていくのをあたしも早く追いつきたいです"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_vassago_1#originalText","id":"talk.vc.home_rank_vassago_1","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"你不需要提升等级，乖乖被我杀掉就好。","en":"There's no point in ranking up. Because you'll quietly be killed by me.","ja":"ランクアップなんざ、する必要はねえおとなしく俺に殺されろ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_vassago_2#originalText","id":"talk.vc.home_rank_vassago_2","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"啧，又提升等级了吗。现在还不算什么，但再变强就麻烦了。","en":"Tch. Looks like you ranked up. Not such a big deal, but it'll be a problem later on.","ja":"ちっ、ランクアップしたのかまだ大したことはねぇがこれ以上は厄介だな"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_vassago_3#originalText","id":"talk.vc.home_rank_vassago_3","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"要杀掉就趁现在，不然可能就来不及了。","en":"If you're going to kill me, better do it now than never. Because I can't guarantee that you'll still have hands to use!","ja":"殺るなら今のうちじゃねぇと手がつけられなくなるかもしれねぇな"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_vassago_4#originalText","id":"talk.vc.home_rank_vassago_4","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"抱歉，我拒绝从正面1对1比试。我怕会有个万一。","en":"Sorry, but I advise that you stop doing 1 on 1 matches. That is, if you get the chance.","ja":"悪いが、正面から1対1で戦うのはやめておくぜ万が一、があるからな"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_vassago_5#originalText","id":"talk.vc.home_rank_vassago_5","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"真有趣。用这双手杀了这么强的家伙，也别具一番风味。","en":"Very interesting. You've gotten so strong! I can't wait to kill you with these hands!","ja":"面白ぇ。そこまで強くなったヤツをこの手で殺すのもまた一興だぜ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_vector_1#originalText","id":"talk.vc.home_rank_vector_1","speaker":{"cn":"Subtilizer","en":"Subtilizer"},"text":{"cn":"你这实力不值一提。","en":"Your strength still has a ways to go."},"kind":"dialogue"},{"uid":"talk.vc.home_rank_vector_4#originalText","id":"talk.vc.home_rank_vector_4","speaker":{"cn":"Subtilizer","en":"Subtilizer"},"text":{"cn":"喔，变得有趣起来了。以这个步调锻炼下去，大概会炼成一个甘美的灵魂吧。","en":"Well, well. Things just got interesting. If you keep training at that rate, your soul will surely be delicious."},"kind":"dialogue"},{"uid":"talk.vc.home_rank_vector_5#originalText","id":"talk.vc.home_rank_vector_5","speaker":{"cn":"Subtilizer","en":"Subtilizer"},"text":{"cn":"很好。就让我好好品尝你的灵魂吧。","en":"Perfection. Adjust the taste of your soul with care."},"kind":"dialogue"},{"uid":"talk.vc.home_rank_yui_1#originalText","id":"talk.vc.home_rank_yui_1","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"好厉害！爸爸愈来愈强了呢！","en":"How impressive! You just keep getting stronger and stronger!","ja":"すごいです!どんどん強くなっちゃいますね!"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_yui_2#originalText","id":"talk.vc.home_rank_yui_2","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"哇……我完全看不到剑的动向！","en":"Wow...I can't even see your sword, it's moving so swiftly!","ja":"うわあ……剣の動きが全然見えません!"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_yui_3#originalText","id":"talk.vc.home_rank_yui_3","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"这样就能好好保护妈妈了呢！","en":"Now you're definitely strong enough to protect Mom from anything!","ja":"これならちゃんとママを守ってあげられますね!"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_yui_4#originalText","id":"talk.vc.home_rank_yui_4","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"我一路看着爸爸努力过来，能够结果真是太好了。","en":"I've watched you struggle all this time. I'm glad your efforts finally paid off.","ja":"ずっと努力するところを見てました努力が実ってよかったです"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_yui_5#originalText","id":"talk.vc.home_rank_yui_5","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"呵呵，不论爸爸变得多强，对我都一样很温柔……我最喜欢爸爸了！","en":"Hehe, no matter how strong you get, you're still always so gentle with me. I love you so much!","ja":"ふふ、どんなに強くなっても私にはとってもやさしい……そんなパパが大好きです!"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_yuna_1#originalText","id":"talk.vc.home_rank_yuna_1","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"恭喜升级－－！你好像不停地在变强呢！","en":"Congrats on ranking up! You're quickly getting stronger, eh.","ja":"ランクアップおめでとー!なんか、どんどん強くなっていくね!"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_yuna_2#originalText","id":"talk.vc.home_rank_yuna_2","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"又升级了呢。呵呵，看起来更可靠了！","en":"Looks like you ranked up again! Fufu, I can count on your for the next step!","ja":"またランクアップしたんだねふふ、一段と頼もしく見えるよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_yuna_3#originalText","id":"talk.vc.home_rank_yuna_3","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"你变得好强喔－－这样的话，不管出现什么敌人都不会输呢！","en":"You're so strong now! Any enemy that pops out won't stand a chance!","ja":"すっごく強くなったねーそれなら、どんな敵が出てきても負けないよね!"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_yuna_4#originalText","id":"talk.vc.home_rank_yuna_4","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"看到你变强了，我就像变强的是我自己一样地开心。","en":"Seeing you get this strong, makes me happy as though it's me who's done the work. Strange... isn't it?","ja":"あなたが強くなると、なんだか自分のことみたいにうれしくなるのヘン……かな?"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_yuna_5#originalText","id":"talk.vc.home_rank_yuna_5","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"能走到这一步，想必发生了很多艰辛的事……但你战胜了一切呢。","en":"I'm sure that you had many difficulties and challenges making it this far ...but in the end you overcame all of them.","ja":"きっとここまで来るのには大変なこともいっぱいあったと思うけど……それに打ち勝ったんだね"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_yuuki_1#originalText","id":"talk.vc.home_rank_yuuki_1","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"你好像升级了，但还有得练呢。","en":"Looks like you just ranked up. But you’ve still got a long way to go!","ja":"ランクアップしたみたいだけどまだまだだね"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_yuuki_2#originalText","id":"talk.vc.home_rank_yuuki_2","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"咦，你又变强啦？可是我也没输你喔！","en":"Oh, you got stronger again? But you still don't hold a candle to me!","ja":"あれ、また強くなった? でもボクだって負けてないよ! "},"kind":"dialogue"},{"uid":"talk.vc.home_rank_yuuki_3#originalText","id":"talk.vc.home_rank_yuuki_3","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"你的剑速提升了不少呢。好，来比划吧！","en":"Judging by your sword's speed, it looks like you raised your rank again. Okay, I challenge you to a duel!","ja":"その剣のスピードかなりランクが上がったねよし、勝負しよう! "},"kind":"dialogue"},{"uid":"talk.vc.home_rank_yuuki_4#originalText","id":"talk.vc.home_rank_yuuki_4","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"只要看着你那么强的样子，我就会止不住兴奋！我也一定会变强的！","en":"When I see how strong you've become, I can't stop fangirling! But I'm gonna be just as strong as you!","ja":"キミの強さを見てるとわくわくが止まらないんだ! ボクだって、もっと強くなるよ! "},"kind":"dialogue"},{"uid":"talk.vc.home_rank_yuuki_5#originalText","id":"talk.vc.home_rank_yuuki_5","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"我可能已经赢不过你了呢。不过总有一天，我一定会追上你的！","en":"You're out of my league now. But someday I'll catch up to you!","ja":"もう、ボクなんか敵わないかなでもいつか、キミに追いついてみせるから! "},"kind":"dialogue"},{"uid":"talk.vc.home_ranyu_dil_1#originalText","id":"talk.vc.home_ranyu_dil_1","speaker":{"cn":"蒂伊‧艾‧耶尔","en":"Dee Eye Ell","ja":"ディー・アイ・エル"},"text":{"cn":"我被发现了？竟然可以看穿我的术式……你也有点能耐嘛。","en":"Did you find it? I did not think that you could detect my technique...","ja":"見つかった?この私の術を見破るとは……少しはできるようね"},"kind":"dialogue"},{"uid":"talk.vc.home_ranyu_eugeo_integrator_1#originalText","id":"talk.vc.home_ranyu_eugeo_integrator_1","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"欠番","en":"欠番","ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_ranyu_eugeo_integrator_2#originalText","id":"talk.vc.home_ranyu_eugeo_integrator_2","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"欠番","en":"欠番","ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_ranyu_eugeo_integrator_3#originalText","id":"talk.vc.home_ranyu_eugeo_integrator_3","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"欠番","en":"欠番","ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_ranyu_eugeo_integrator_4#originalText","id":"talk.vc.home_ranyu_eugeo_integrator_4","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"欠番","en":"欠番","ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_ranyu_eugeo_integrator_5#originalText","id":"talk.vc.home_ranyu_eugeo_integrator_5","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"欠番","en":"欠番","ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_ranyu_eugeo_integrator_6#originalText","id":"talk.vc.home_ranyu_eugeo_integrator_6","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"欠番","en":"欠番","ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_ranyu_eugeo_integrator_7#originalText","id":"talk.vc.home_ranyu_eugeo_integrator_7","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"欠番","en":"欠番","ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_ranyu_eugeo_integrator_8#originalText","id":"talk.vc.home_ranyu_eugeo_integrator_8","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"欠番","en":"欠番","ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_ranyu_eugeo_integrator_9#originalText","id":"talk.vc.home_ranyu_eugeo_integrator_9","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"欠番","en":"欠番","ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_ranyu_eugeo_integrator_10#originalText","id":"talk.vc.home_ranyu_eugeo_integrator_10","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"欠番","en":"欠番","ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_ranyu_eugeo_integrator_11#originalText","id":"talk.vc.home_ranyu_eugeo_integrator_11","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"欠番","en":"欠番","ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_ranyu_eugeo_integrator_12#originalText","id":"talk.vc.home_ranyu_eugeo_integrator_12","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"欠番","en":"欠番","ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_ranyu_eugeo_integrator_13#originalText","id":"talk.vc.home_ranyu_eugeo_integrator_13","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"欠番","en":"欠番","ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_ranyu_eugeo_integrator_14#originalText","id":"talk.vc.home_ranyu_eugeo_integrator_14","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"欠番","en":"欠番","ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_ranyu_eugeo_integrator_15#originalText","id":"talk.vc.home_ranyu_eugeo_integrator_15","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"欠番","en":"欠番","ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_ranyu_eugeo_integrator_16#originalText","id":"talk.vc.home_ranyu_eugeo_integrator_16","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"欠番","en":"欠番","ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_ranyu_iskahn_1#originalText","id":"talk.vc.home_ranyu_iskahn_1","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"终于找到你了！喂，过来这边！跟我决一胜负！","en":"I finally found you! Come on over here! Fight me!","ja":"やっと見つけたぞ!ほら、こっちに来い!俺と勝負だ!"},"kind":"dialogue"},{"uid":"talk.vc.home_ranyu_iskahn_2#originalText","id":"talk.vc.home_ranyu_iskahn_2","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"虽然很久没见你，但你一点都没变。吃多点肉啊。","en":"It's been awhile since we've last met, but you haven't changed one bit. You need to eat more meat!","ja":"久しぶりだけど、お前は全然変わってねえなもっと肉を食え"},"kind":"dialogue"},{"uid":"talk.vc.home_ranyu_lipia_1#originalText","id":"talk.vc.home_ranyu_lipia_1","speaker":{"cn":"莉琵雅","en":"Lipia","ja":"リピア"},"text":{"cn":"好久不见，阁下。看到阁下安然无恙，我也安心了。","en":"Long time no see, my Lord. I am always glad to see that you have not changed one bit.","ja":"お久しぶりです、閣下閣下の変わらぬお顔を見られて嬉しく思います"},"kind":"dialogue"},{"uid":"talk.vc.home_ranyu_renri_1#originalText","id":"talk.vc.home_ranyu_renri_1","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"啊，对不起……我好像有点迷路了。","en":"Oh...s-sorry! Looks like I just got lost.","ja":"あっ、ごめん……ちょっと迷っちゃったみたいで"},"kind":"dialogue"},{"uid":"talk.vc.home_ranyu_renri_2#originalText","id":"talk.vc.home_ranyu_renri_2","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"总觉得，已经很久没有像这样跟别人说话了。……我觉得很开心。","en":"It's been awhile since I've talked like this. ...It's a good feeling.","ja":"なんだか、こうして話すのは久しぶりだね……僕は、うれしいな"},"kind":"dialogue"},{"uid":"talk.vc.home_ranyu_scheta_1#originalText","id":"talk.vc.home_ranyu_scheta_1","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"……妨碍到你真不好意思。","en":"...I apologize for intruding.","ja":"……邪魔をしてごめんなさい"},"kind":"dialogue"},{"uid":"talk.vc.home_ranyu_scheta_2#originalText","id":"talk.vc.home_ranyu_scheta_2","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"是谁？……原来是你吗。","en":"Who is it? ...Was that you?","ja":"誰?……あなた、だったの"},"kind":"dialogue"},{"uid":"talk.vc.home_ranyu_subtilizer_1#originalText","id":"talk.vc.home_ranyu_subtilizer_1","speaker":{"ja":"サトライザー"},"text":{"ja":"……気をつけろ次に目の前にその顔を出せば警告無しに叩き切る"},"kind":"dialogue"},{"uid":"talk.vc.home_ranyu_subtilizer_2#originalText","id":"talk.vc.home_ranyu_subtilizer_2","speaker":{"ja":"サトライザー"},"text":{"ja":"チッ、このようなところに来るつもりはなかったのだが……"},"kind":"dialogue"},{"uid":"talk.vc.home_ranyu_tiese_child_1#originalText","id":"talk.vc.home_ranyu_tiese_child_1","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"不好意思，突然找您……我有打扰到您吗？","en":"My apologies for the suddenness... Did I get in the way?","ja":"すみません、突然……邪魔しちゃった?"},"kind":"dialogue"},{"uid":"talk.vc.home_ranyu_tiese_child_2#originalText","id":"talk.vc.home_ranyu_tiese_child_2","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"请问……可以跟我一起练剑吗？","en":"Um...Could you do sword practice with me?","ja":"あの……一緒に剣の稽古をしてくれませんか?"},"kind":"dialogue"},{"uid":"talk.vc.home_ranyu_vassago_1#originalText","id":"talk.vc.home_ranyu_vassago_1","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"……看什么看。还是说你想尝尝这把《杀友菜刀》的滋味呢？","en":"...What are you looking at? Or are you interested in getting a taste of my 'Mate Chopper'?","ja":"……なに見てやがる。それともここでコイツ《友切包丁》の切れ味を味わってみるか？"},"kind":"dialogue"},{"uid":"talk.vc.home_ranyu_vassago_2#originalText","id":"talk.vc.home_ranyu_vassago_2","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"WoW！竟然可以察觉到我的气息……你是怎样发现的？","en":"Wow! You noticed my presence... How did you know?","ja":"WoW!俺の気配に気づくとはな……どうしてわかった?"},"kind":"dialogue"},{"uid":"talk.vc.home_ranyu_vector_1#originalText","id":"talk.vc.home_ranyu_vector_1","speaker":{"cn":"Subtilizer","en":"Subtilizer"},"text":{"cn":"……小心点。下次再在我面前露出那种表情我不会再作任何警告直接斩下去。","en":"...Careful. Next time you show your face in front of me, I'll chop you up without a warning."},"kind":"dialogue"},{"uid":"talk.vc.home_ranyu_vector_2#originalText","id":"talk.vc.home_ranyu_vector_2","speaker":{"cn":"Subtilizer","en":"Subtilizer"},"text":{"cn":"啧，我并没有想要来这种地方……","en":"Tch. I wasn't planning on coming to a place like this, but..."},"kind":"dialogue"},{"uid":"talk.vc.home_season_administrator_1#originalText","id":"talk.vc.home_season_administrator_1","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"看着在这个季节出生的金鸢狐幼崽，就会觉得很怀念呢。","en":"Whenever I watch the baby golden flying foxes in the spring, I start to feel sentimental.","ja":"この時期に生まれるキントビギツネの仔を見るとなんとなく懐かしくなるわ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_administrator_2#originalText","id":"talk.vc.home_season_administrator_2","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"感受得到暑气很不方便呢。要是可以调整就好了。","en":"How inconvenient to feel the heat. I wish I could make some weather adjustments.","ja":"暑さを感じるなんて、不便ね調整できればいいのに"},"kind":"dialogue"},{"uid":"talk.vc.home_season_administrator_3#originalText","id":"talk.vc.home_season_administrator_3","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"暴风雨就要来了。我想这座塔应该是没什么问题，但姑且还是保持警戒吧。","en":"A storm is coming. This tower should be all right, but I want you to check and make sure.","ja":"もうすぐ嵐が来るわこの塔は大丈夫だと思うけど一応警戒しておきなさい"},"kind":"dialogue"},{"uid":"talk.vc.home_season_administrator_4#originalText","id":"talk.vc.home_season_administrator_4","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"一年又要结束了呢。这个世界会像这样，继续刻画着一样的时间。","en":"Another year is ending. But this world will continue to cycle through the same time, year after year.","ja":"また一年が終わるのね……あなたは何も心配しなくていいのよ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_agil_1#originalText","id":"talk.vc.home_season_agil_1","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"下次要不要找大家一起去赏花？","en":"Wanna go on a picnic with the gang soon?","ja":"今度みんなを集めて花見にでも行くか?"},"kind":"dialogue"},{"uid":"talk.vc.home_season_agil_2#originalText","id":"talk.vc.home_season_agil_2","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"我这发型在夏天很凉快喔，你要不要也试试看？","en":"My hairstyle is nice and cool for hot days. You should try it.","ja":"この髪型、夏は涼しいぞお前も試してみたらどうだ?"},"kind":"dialogue"},{"uid":"talk.vc.home_season_agil_3#originalText","id":"talk.vc.home_season_agil_3","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"秋天有很多出色的食材嘛，我来想想新菜色好了。","en":"Autumn does have lots of tasty produce. Maybe I should come up with some new menu items.","ja":"秋はいい食材が多いからな新メニューを考えてみるか"},"kind":"dialogue"},{"uid":"talk.vc.home_season_agil_4#originalText","id":"talk.vc.home_season_agil_4","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"像今天这么冷的日子，生意也很凄凉啊……","en":"On cold days like this, business sure is slow.","ja":"今日みたいな寒い日は商売の方も寂しくてな……"},"kind":"dialogue"},{"uid":"talk.vc.home_season_alice_1#originalText","id":"talk.vc.home_season_alice_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"萌发的绿芽，我喜欢那份娇嫩。真希望它们能够成长茁壮。","en":"I love the young, fresh new buds of spring. I hope they grow up big and strong.","ja":"萌え出る新芽は、初々しくて好きです大きく育ってほしいですね"},"kind":"dialogue"},{"uid":"talk.vc.home_season_alice_2#originalText","id":"talk.vc.home_season_alice_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"不过是些暑气，可容不下丧气话。这点气温，只要鼓足干劲……！","en":"Don't cry over a little summer heat. Shake it off with a vigorous spirit!","ja":"暑さくらいでは泣き言を言っていられませんこの程度、気合があれば……!"},"kind":"dialogue"},{"uid":"talk.vc.home_season_alice_3#originalText","id":"talk.vc.home_season_alice_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"秋天有收获祭吧。诸如水果等物会特别好吃……我听说是这样。","en":"So you have Harvest Festivals in autumn. I heard that the fruit in particular is quite delicious.","ja":"秋には収穫祭がありますね果物などが非常においしい……と、聞きました"},"kind":"dialogue"},{"uid":"talk.vc.home_season_alice_4#originalText","id":"talk.vc.home_season_alice_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"看到水面结上一层冰，不知为何胸口就会隐隐作痛。……难道，是因为天冷吗？","en":"Whenever I see ice on the water's surface, I feel a pain in my heart. Perhaps it is from the cold air...","ja":"水面に氷が張るのを見るとなぜか胸が少し痛みます……寒さのせい、でしょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_season_alice_child_1#originalText","id":"talk.vc.home_season_alice_child_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"一到春天就会开好多花，很美呢。","en":"I love spring. It's so pretty, with all the flowers.","ja":"春になるとお花がいっぱいですごくキレイよね"},"kind":"dialogue"},{"uid":"talk.vc.home_season_alice_child_2#originalText","id":"talk.vc.home_season_alice_child_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"啊～啊～真羡慕男孩子。我就不能这样直接跳进水里的说。","en":"Oooh, the water looks so cool. I wish I could just jump right in!","ja":"あーあ、男の子がうらやましいさすがに、このままお水に飛び込むわけにはいかないもんね"},"kind":"dialogue"},{"uid":"talk.vc.home_season_alice_child_3#originalText","id":"talk.vc.home_season_alice_child_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"这次我要挑战新口味的派！这个季节的水果很好吃，你就好好期待吧！","en":"I'm testing out a new pie recipe tomorrow! Lots of fruit is in season right now, so it's going to be a good one!","ja":"今度、新作のパイに挑戦するの! 果物がおいしい節だから楽しみにしてて! "},"kind":"dialogue"},{"uid":"talk.vc.home_season_alice_child_4#originalText","id":"talk.vc.home_season_alice_child_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"呼……你看！呼出来的气好白！","en":"Haaah... Oooh, look at how white my breath is!","ja":"はあー……ほら見て! 息がこんなに白い! "},"kind":"dialogue"},{"uid":"talk.vc.home_season_argo_1#originalText","id":"talk.vc.home_season_argo_1","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"感觉春天就像一年的开始呢。今年也请你多多指教啰。","en":"Spring feels like the start of a new year. So, Happy New Year, I guess?","ja":"春は一年のスタートって感じダナ今年もよろしく頼むヨ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_argo_2#originalText","id":"talk.vc.home_season_argo_2","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"天气热的时候，不知为何就会得到一堆超自然的情报耶。","en":"Whenever the weather gets hot, I get a lot of occult intel for some reason.","ja":"暑い時には、なぜかオカルト的な情報がたくさん入ってくるんだよナ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_argo_3#originalText","id":"talk.vc.home_season_argo_3","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"枫叶啊……我没什么兴趣呢。不说那个了，我这里有个有趣的情报喔。","en":"You wanna see the autumn leaves? Not really my thing. But some juicy intel just came in...","ja":"紅葉ねエ……あんまり興味ないナそれより、面白い情報があるんだヨ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_argo_4#originalText","id":"talk.vc.home_season_argo_4","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"冷天就会觉得有连帽斗篷真好……你要不要试着穿穿看？","en":"I'm really grateful for my hood on cold days. Wanna try it on for size?","ja":"寒い時はフードがありがたいヨ……試しにかぶってみるカ?"},"kind":"dialogue"},{"uid":"talk.vc.home_season_asuna_1#originalText","id":"talk.vc.home_season_asuna_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"赏花便当里面装什么好呢？","en":"What do you want me to put in our cherry blossom picnic lunch?","ja":"お花見のお弁当中身は何がいいかな? "},"kind":"dialogue"},{"uid":"talk.vc.home_season_asuna_2#originalText","id":"talk.vc.home_season_asuna_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"可不能因为是夏天，就让自己显得太过邋遢喔。","en":"Just because it's summer, that's no excuse to go full-slob on me.","ja":"夏だからって、あんまりだらしない格好はしちゃダメだからね"},"kind":"dialogue"},{"uid":"talk.vc.home_season_asuna_3#originalText","id":"talk.vc.home_season_asuna_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"秋天的餐点好吃到令人困扰，一不小心就会吃太多呢。","en":"Why does food have to taste so good in the fall? Now I want to eat all the things!","ja":"秋はご飯がおいしくてこまっちゃうつい食べ過ぎちゃうの"},"kind":"dialogue"},{"uid":"talk.vc.home_season_asuna_4#originalText","id":"talk.vc.home_season_asuna_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"冬天骑车不冷吗？换作是我感觉会冻死。","en":"Aren't you cold riding a bike in the winter? I'd freeze my butt off.","ja":"冬にバイクって、寒くないの? わたしだったら、凍えちゃいそう"},"kind":"dialogue"},{"uid":"talk.vc.home_season_bercouli_1#originalText","id":"talk.vc.home_season_bercouli_1","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"这个季节很适合飞在空中。景色既好，更重要的是天不冷。","en":"It's the perfect season for flying. The views are great, and it's not too chilly.","ja":"空を飛ぶにはいい季節だ眺めもいいし、何より寒くない"},"kind":"dialogue"},{"uid":"talk.vc.home_season_bercouli_2#originalText","id":"talk.vc.home_season_bercouli_2","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"热成这样实在受不了耶。还是去冲凉好啦？","en":"It’s too hot to get anything done. Want to go swimming?","ja":"こう暑くちゃ、やってられないよな水浴びでもするか?"},"kind":"dialogue"},{"uid":"talk.vc.home_season_bercouli_3#originalText","id":"talk.vc.home_season_bercouli_3","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"收获的季节嘛，有没有哪里推出好吃的啊？","en":"It's harvest season, I hear. Any good fruit out there?","ja":"収穫の季節だななにかうまいものは出てくるのか?"},"kind":"dialogue"},{"uid":"talk.vc.home_season_bercouli_4#originalText","id":"talk.vc.home_season_bercouli_4","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"我有点怕冷呢。在这个季节，星咬的翅膀也都要冻僵了。","en":"I'm not a big fan of cold weather. My dragon's wings get weak, too.","ja":"寒さってのはちょいと苦手だなこの季節は、星咬の翼もかじかんじまうんだよ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_cardinal_1#originalText","id":"talk.vc.home_season_cardinal_1","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"在春天诞生的动物幼雏……为何总是如此可爱呢？","en":"Animals born in the spring... Why are they so adorable?","ja":"春に生まれる動物の赤子……あれはなぜあんなにもかわいいのであろうな?"},"kind":"dialogue"},{"uid":"talk.vc.home_season_cardinal_2#originalText","id":"talk.vc.home_season_cardinal_2","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"在这座图书馆里，没有所谓气候的冷热。……虽然这样也是有些寂寞呢。","en":"This library is never too cold nor too hot. Though at times...it can feel empty.","ja":"この図書館の中は暑さや寒さは関係ない……少し寂しくもあるが、な"},"kind":"dialogue"},{"uid":"talk.vc.home_season_cardinal_3#originalText","id":"talk.vc.home_season_cardinal_3","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"明明没有记忆，却会在这个季节感到莫名心伤。连我自己都感觉不可思议啊。","en":"I shouldn't have any memories from my past life, but I always feel melancholy during this season. A surreal feeling indeed.","ja":"感情はなくなっておるのにこの季節には物悲しさを覚える我ながら不思議な感覚じゃ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_cardinal_4#originalText","id":"talk.vc.home_season_cardinal_4","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"哪怕一次也好，我想要亲手确认雪这个东西的感觉。","en":"I would love to be able to touch snow just once, with my own hands.","ja":"雪、というものの感覚を一度でいいからこの手で確かめてみたいものじゃ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_deusolbert_1#originalText","id":"talk.vc.home_season_deusolbert_1","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"看着春天的景色，有时胸口会没来由地作痛……","en":"Whenever I see spring's colors, my heart aches for no reason.","ja":"春の景色を見ているとわけもなく、胸が痛くなることがある……"},"kind":"dialogue"},{"uid":"talk.vc.home_season_deusolbert_2#originalText","id":"talk.vc.home_season_deusolbert_2","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"集成骑士是没得抱怨天气冷热的。","en":"Integrity Knights have no time to waste complaining about the weather.","ja":"整合騎士は、暑い寒いなどといってはおれぬのだ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_deusolbert_3#originalText","id":"talk.vc.home_season_deusolbert_3","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"夜晚渐长，这个季节必须加强警戒。","en":"When the nights are long, one must be vigilant.","ja":"夜が長くなってきたこの季節は、警戒が必要だぞ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_deusolbert_4#originalText","id":"talk.vc.home_season_deusolbert_4","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"从飞龙背上眺望被雪染白的世界，感觉相当不错。","en":"When the world is white, beholding the landscape from a dragon's back is a lovely thing indeed.","ja":"雪で白く染まった世界を飛竜から眺めるのはなかなか悪くない"},"kind":"dialogue"},{"uid":"talk.vc.home_season_edith_1#originalText","id":"talk.vc.home_season_edith_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"一旦冒出小花苞，就很有春天的感觉了。","en":"When little flower buds pop out, it truly feels like spring is here.","ja":"小さい花のつぼみが出てくると春になったなと感じるの"},"kind":"dialogue"},{"uid":"talk.vc.home_season_edith_2#originalText","id":"talk.vc.home_season_edith_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"太热的天不出门，这样最好。","en":"Never go outside on hot days. That's the best policy.","ja":"暑すぎる日は外に出ないこれが一番よ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_edith_3#originalText","id":"talk.vc.home_season_edith_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"在这个时期，东边的山地也被染得一片通红。要不要去看看？","en":"During this time of year, the eastern mountains turn red. Would you like to go see them with me?","ja":"東の山も、この時期は赤く染まってるの見に行ってみる? "},"kind":"dialogue"},{"uid":"talk.vc.home_season_edith_4#originalText","id":"talk.vc.home_season_edith_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"湖面上结了一层薄冰。今天是有多冷啊……","en":"The lake's surface is frozen. That's just how cold it is today.","ja":"湖の上に薄く氷が張ってるどれだけ寒いのよ、今日は……"},"kind":"dialogue"},{"uid":"talk.vc.home_season_eldrie_1#originalText","id":"talk.vc.home_season_eldrie_1","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"这个时期，一边赏花一边把酒言欢，也不错呢。","en":"I do like the spring custom of drinking wine whilst admiring the blossoms.","ja":"この時期は、花を見ながら杯を傾ける、というのも悪くないですよ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_eldrie_2#originalText","id":"talk.vc.home_season_eldrie_2","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"您问我的这身汗吗……？只是稍微挥了几下剑而已。毕竟要时常勤加修练嘛。","en":"Why am I sweating, you ask? I was just taking some practice-swings. A knight's training is never finished.","ja":"この汗ですか……?少し素振りをしていただけですよ常に修練あるのみですから"},"kind":"dialogue"},{"uid":"talk.vc.home_season_eldrie_3#originalText","id":"talk.vc.home_season_eldrie_3","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"现在是洋兰盛开的季节呢。四大圣花之中，还是洋兰最美。","en":"The cattleya really shine this time of year. Cattleyas are the prettiest among the Four Holy Flowers.","ja":"この季節はカトレアが盛りですね四大聖花の中では、やはりカトレアが最も美しい"},"kind":"dialogue"},{"uid":"talk.vc.home_season_eldrie_4#originalText","id":"talk.vc.home_season_eldrie_4","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"我认为正是这个季节，才更应该增加对暗之子民的防范。","en":"It is because we are in this season that we must remain ever vigilant with the Dark forces.","ja":"このような季節こそ闇の輩への備えを増さねばならない、と考えます"},"kind":"dialogue"},{"uid":"talk.vc.home_season_entokia_integrator_1#originalText","id":"talk.vc.home_season_entokia_integrator_1","speaker":{"cn":"恩特基尔","en":"Entokia","ja":"エントキア"},"text":{"cn":"天气暖洋洋的真舒服啊。这种日子就是要享受午觉，对吧老师？","en":"What a nice, warm day. Days like this are just perfect for napping. Wouldn't you agree, Master?","ja":"ぽかぽか陽気ですなあこんな日は昼寝に限るそうですよね、先生"},"kind":"dialogue"},{"uid":"talk.vc.home_season_entokia_integrator_2#originalText","id":"talk.vc.home_season_entokia_integrator_2","speaker":{"cn":"恩特基尔","en":"Entokia","ja":"エントキア"},"text":{"cn":"我非常耐热喔。运动流汗之后，总觉得通体舒畅呢。","en":"I actually thrive on hot days. Something about moving my body and sweating really hits the spot!","ja":"暑いのは得意なんですよ体動かして汗をかくとなんだかスッキリするんですわ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_entokia_integrator_3#originalText","id":"talk.vc.home_season_entokia_integrator_3","speaker":{"cn":"恩特基尔","en":"Entokia","ja":"エントキア"},"text":{"cn":"呜呜，天气开始转凉了。这种日子最好吃点热食，早早就寝。","en":"Ack, it's getting colder. On days like this, it's best to eat something warm and go straight to bed.","ja":"うう、涼しくなってきましたなこんな日は温かいモンでも食べて、早く寝ちゃいましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_season_entokia_integrator_4#originalText","id":"talk.vc.home_season_entokia_integrator_4","speaker":{"cn":"恩特基尔","en":"Entokia","ja":"エントキア"},"text":{"cn":"拜托别在下雪天派我出任务……这种丧气话可说不得呢，我马上搞定。","en":"I'd love to just skip work when it snows...but I know I can't. Let's just get this over with.","ja":"雪の日の任務は勘弁……なんて言ってられないっすよねちゃちゃっと片付けてきます"},"kind":"dialogue"},{"uid":"talk.vc.home_season_eugeo_1#originalText","id":"talk.vc.home_season_eugeo_1","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"原野的花增加了，天气总算要变暖和了呢。","en":"When the fields are full of flowers, that's a sign that warm weather is finally returning.","ja":"野原に花が増えてきたねやっと暖かくなるね"},"kind":"dialogue"},{"uid":"talk.vc.home_season_eugeo_2#originalText","id":"talk.vc.home_season_eugeo_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"天气一变热，我就会想起那天的事情。想起什么事都做不了，不可原谅的自己……","en":"When the weather gets hot, I always remember that day. The day where I was paralyzed with fear and hated myself for it...","ja":"暑くなってくると、あの日を思い出すんだ。何もできなくて自分を許せなかったあの日を……"},"kind":"dialogue"},{"uid":"talk.vc.home_season_eugeo_3#originalText","id":"talk.vc.home_season_eugeo_3","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"这个季节会有很多水果，下次一起去摘吧。","en":"We should go out fruit-picking. A lot of fruits get ripe this time of year.","ja":"この季節はいろんな果物がなるから、今度採りに行こうか"},"kind":"dialogue"},{"uid":"talk.vc.home_season_eugeo_4#originalText","id":"talk.vc.home_season_eugeo_4","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"冬天挥动斧头很辛苦，但是挥剑却很快乐呢。","en":"Swinging my axe in the winter was always tough, but swinging a sword feels good.","ja":"冬の斧振りは辛かったけど剣を振るのは楽しいよ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_eugeo_child_1#originalText","id":"talk.vc.home_season_eugeo_child_1","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"一到这个季节，就会有「一年又要开始了」的感觉呢。","en":"Whenever this season rolls around, I always think about a new year coming to life.","ja":"この季節になるとまた一年が始まるなっていう気持ちになるんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_eugeo_child_2#originalText","id":"talk.vc.home_season_eugeo_child_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"唔哇，流了好多汗……我们休息一下吧？","en":"Wow, I'm soaked in sweat. Let's take a little break.","ja":"うわあ、汗でびしょびしょだ……ちょっと休憩しようか"},"kind":"dialogue"},{"uid":"talk.vc.home_season_eugeo_child_3#originalText","id":"talk.vc.home_season_eugeo_child_3","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"天气总算变得舒爽了。只是风有点冷。","en":"It's finally gotten more comfortable outside. But the wind is a bit chilly.","ja":"やっと過ごしやすくなってきたねちょっと風が冷たいけど"},"kind":"dialogue"},{"uid":"talk.vc.home_season_eugeo_child_4#originalText","id":"talk.vc.home_season_eugeo_child_4","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"只要一下雪，心情就会不由得雀跃。这是为什么呢？","en":"I always get excited for the first snowfall. I wonder why that is?","ja":"雪が降ると、なんだかわくわくしちゃうんだなんでだろうね"},"kind":"dialogue"},{"uid":"talk.vc.home_season_fanatio_1#originalText","id":"talk.vc.home_season_fanatio_1","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"新生命诞生的季节……果然会让人为之雀跃呢。","en":"A season filled with rebirth... How it does lift the spirit.","ja":"新たな生命が生まれる季節は……やはり心が浮き立ちますね"},"kind":"dialogue"},{"uid":"talk.vc.home_season_fanatio_2#originalText","id":"talk.vc.home_season_fanatio_2","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"就算天气再热，也不能脱下这身铠甲！","en":"No matter how hot the weather is, I refuse to remove my armor!","ja":"いくら暑くても、この鎧を外すわけには参りません!"},"kind":"dialogue"},{"uid":"talk.vc.home_season_fanatio_3#originalText","id":"talk.vc.home_season_fanatio_3","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"听到这股风声，就开始感到些许寒意了。","en":"Listening to the sound of the wind makes life feel rather bleak.","ja":"この風の音を聞いていると少し寒々しい気がします"},"kind":"dialogue"},{"uid":"talk.vc.home_season_fanatio_4#originalText","id":"talk.vc.home_season_fanatio_4","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"一旦有雪跟冰，就不容易站稳。有必要针对这点进行锻炼呢。","en":"When it snows, the roads are slippery with ice. We must train further for this terrain.","ja":"雪や氷があると、足元が不安定になりますそのための修練も必要ですね"},"kind":"dialogue"},{"uid":"talk.vc.home_season_fizel_1#originalText","id":"talk.vc.home_season_fizel_1","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"因为天气变暖，所以我早上也起得了床了。","en":"Now that the weather is warmer, it's easier to get up in the morning.","ja":"暖かくなってきたから朝起きられるようになってきたわ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_fizel_2#originalText","id":"talk.vc.home_season_fizel_2","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"夏天穿这件修道服会很热，要是衣服能薄一点就好了。","en":"These nun's robes get hot in the summer. I wish the fabric were thinner.","ja":"この修道服、夏は暑いのよねえもっと薄い服になればいいのに"},"kind":"dialogue"},{"uid":"talk.vc.home_season_fizel_3#originalText","id":"talk.vc.home_season_fizel_3","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"秋天叶子会变色啊？不是因为……它们中毒了吗？","en":"The leaves change color in the fall, don't they? It's not because they’re...poisoned, is it?","ja":"秋は葉っぱの色が変わるのね?毒を受けた……というわけじゃないの?"},"kind":"dialogue"},{"uid":"talk.vc.home_season_fizel_4#originalText","id":"talk.vc.home_season_fizel_4","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"石造的建筑很冰冷，好想泡澡温暖身子。","en":"Stone buildings are so cold! I want to warm up in a nice, hot bath!","ja":"石造りの建物は冷えるのお風呂で温まりたーい"},"kind":"dialogue"},{"uid":"talk.vc.home_season_kirito_1#originalText","id":"talk.vc.home_season_kirito_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"这个季节很适合睡午觉呢～我们一起在那里小睡一下吧……","en":"It's prime napping season right now. Let's go have a nap over there.","ja":"昼寝にちょうどいい季節だなあ～ちょっとあっちで一緒にうたた寝しようぜ……"},"kind":"dialogue"},{"uid":"talk.vc.home_season_kirito_2#originalText","id":"talk.vc.home_season_kirito_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"碰上这么热的日子，就会想要吃冰呢。你要吃什么？我帮你买回来。","en":"You know the perfect thing for a hot day like this? Ice cream.  What's your favorite flavor? I'll buy you some.","ja":"こういう暑い日は冷たいアイスが食いたくなるな何がいい? 俺買ってくるよ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_kirito_3#originalText","id":"talk.vc.home_season_kirito_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"外面的枫叶好美啊。要不要去看一下？","en":"The red and orange leaves sure are pretty. Want to go out and look at them?","ja":"外の紅葉がきれいだなちょっと見に行かないか?"},"kind":"dialogue"}]};
